/* ─── Ultimate Autofill: CSV bulk-apply queue engine (additive, self-contained) ───
   Loads the automation orchestrator, the read-only mailbox module and the run
   recorder into this service worker. Nothing above this line is modified, so a
   future Jobright patch can be dropped in and these lines re-appended. A patch
   that ships its own static/background/index.js REPLACES this file and takes
   them with it — which is exactly what tests/run.sh checks for, because without
   them the CSV queue silently does nothing and the recorder records nothing. */
try { importScripts("/ua-orchestrator.js"); } catch (e) { console.warn("[UA] orchestrator failed to load", e); }
try { importScripts("/ua-mailbox.js"); } catch (e) { console.warn("[UA] mailbox failed to load", e); }
try { importScripts("/ua-diagnostics.js"); } catch (e) { console.warn("[UA] diagnostics failed to load", e); }
